{
  "findings": [
    {
      "check_id": "CKV2_GCP_19",
      "title": "Alpha cluster feature enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets `enable_kubernetes_alpha = \"true\"`, which enables alpha features that are not supported for production use and may introduce instability or security vulnerabilities."
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "Legacy Authorization (ABAC) enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The resource sets `enable_legacy_abac = \"true\"`, enabling legacy Attribute-Based Access Control. This is deprecated in favor of RBAC and can lead to overly permissive access controls if not carefully managed."
    },
    {
      "check_id": "CKV_GCP_13",
      "title": "Client certificate authentication enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The `master_auth` block configures `issue_client_certificate = true`. Client certificates are a less secure authentication method compared to OIDC or service accounts, and their issuance should be disabled unless strictly required."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Static credentials in master_auth",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "The `master_auth` block uses static `username` and `password` variables. Static credentials are difficult to rotate and manage securely; modern GKE clusters should rely on IAM integration or OIDC providers instead."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = false\n  enable_legacy_abac = false\n  master_auth {\n    username = \"\"\n    password = \"\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}",
  "fix_summary": "Disabled Kubernetes alpha features (`enable_kubernetes_alpha`) and Legacy ABAC (`enable_legacy_abac`). Disabled client certificate issuance (`issue_client_certificate`) and cleared static username/password fields in `master_auth` to enforce more secure authentication methods."
}
